#include <iostream>
#include <string>
#include <vector>
struct Book { std::string title; bool borrowed = false; };
bool borrow(Book& book) { if (book.borrowed) return false; book.borrowed = true; return true; }
int main() { Book book{"C++ Primer"}; std::cout << std::boolalpha << borrow(book) << ' ' << borrow(book) << '\n'; }
